('b4a1a53f-efd6-4e2a-b3a4-58bb7afd9311', 'question', '{"type": "multiple_choice", "question": "Apa fungsi utama Bursa Efek Indonesia (IDX)?", "options": ["Menerbitkan uang rupiah", "Tempat membeli dan menjual saham di Indonesia", "Mengatur suku bunga bank", "Menyalurkan kredit UMKM"], "answer": "Tempat membeli dan menjual saham di Indonesia", "explanation": "IDX adalah pasar tempat saham dan efek lain diperdagangkan di Indonesia.", "difficulty": "beginner", "parameters": {}}', 'beginner', true),
